import { writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";

const OUT = path.join(path.dirname(fileURLToPath(import.meta.url)), "uploads");

const { CATALOG } = await import("../../lib/dna/catalog.ts");

// Build a realistic-but-small 23andMe raw file: real comment header, then the
// full catalog rsids (so every insight fires) plus some filler SNPs.
function genomeLines() {
  const lines = [
    "# This data file generated by 23andMe at: Wed Jan 01 03:16:03 2026",
    "# This file contains raw genotype data, including data that is not used in 23andMe reports.",
    "# This data has undergone a general quality review however only a subset of markers have been",
    "# individually validated for accuracy.",
    "# Below is a text version of your data.  Fields are TAB-separated",
    "# rsid\tchromosome\tposition\tgenotype",
  ];
  let pos = 80000;
  for (const c of CATALOG) {
    const gt = (c.riskGenotypes && c.riskGenotypes[0]) || "AG";
    const chr = c.chromosome || "1";
    lines.push(`${c.rsid}\t${chr}\t${pos}\t${gt}`);
    pos += 137;
  }
  // filler SNPs (not in catalog)
  for (let i = 0; i < 200; i++) { lines.push(`rs${900000 + i}\t2\t${pos}\tAA`); pos += 53; }
  return lines.join("\n") + "\n";
}

const genome = genomeLines();
writeFileSync(path.join(OUT, "genome_Test_v5_Full_20260101.txt"), genome);

// Zip variant (different rsids count irrelevant; tests the unzip path)
const ztxt = path.join(OUT, "_genome_in_zip.txt");
writeFileSync(ztxt, genome);
try {
  execFileSync("zip", ["-j", "-q", path.join(OUT, "genome_Test_v5.zip"), ztxt]);
} finally {
  execFileSync("rm", ["-f", ztxt]);
}

// AncestryDNA format: 5 columns (rsid chromosome position allele1 allele2)
const anc = [
  "#AncestryDNA raw data download",
  "#The data below corresponds to the genotypes you provided.",
  "rsid\tchromosome\tposition\tallele1\tallele2",
];
let p = 90000;
for (const c of CATALOG.slice(0, 40)) {
  const gt = ((c.riskGenotypes && c.riskGenotypes[0]) || "AG").padEnd(2, "A");
  anc.push(`${c.rsid}\t${c.chromosome || "1"}\t${p}\t${gt[0]}\t${gt[1]}`);
  p += 91;
}
writeFileSync(path.join(OUT, "AncestryDNA.txt"), anc.join("\n") + "\n");

// Minimal valid 1x1 PNG (red pixel) — tests the image branch.
const png = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAAC0lEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==",
  "base64",
);
writeFileSync(path.join(OUT, "resultat-labo.png"), png);

console.log(`DNA: catalog rsids=${CATALOG.length}; wrote genome txt+zip, AncestryDNA.txt, PNG`);
